INSERT INTO site_settings (site_setting_id, contact_email, contact_phone, site_domain, portfolio_company_count, self_description_line, positioning_statement, hero_headline, hero_subheadline, banyan_title)
VALUES ('default', 'david@davidshadle.com', '425.417.2339', 'davidshadle.com', '100+', 'A full stack product practitioner. Not just capable of wearing several hats at once, but confident delivering the outcome in each one.', 'I build the systems that turn strategy into working software. Most advisors stop at the recommendation. I keep going, through the model, the interface, and the handoff, so the thing that gets agreed on is the thing that gets shipped. I work from a rulebook: the rules of a domain written down once in plain language, with the technical pieces derived from that rather than maintained by hand. It is a discipline, not a product. It is what lets me carry a project through delivery instead of stopping at design and project management.', 'I build the systems that turn strategy into working software.', 'Most advisors stop at the recommendation. I keep going, through the model, the interface, and the handoff, so the thing that gets agreed on is the thing that gets shipped.', 'Technical Advisor, Product Strategy and UX') ON CONFLICT (site_setting_id) DO UPDATE SET contact_email = EXCLUDED.contact_email, contact_phone = EXCLUDED.contact_phone, site_domain = EXCLUDED.site_domain, portfolio_company_count = EXCLUDED.portfolio_company_count, self_description_line = EXCLUDED.self_description_line, positioning_statement = EXCLUDED.positioning_statement, hero_headline = EXCLUDED.hero_headline, hero_subheadline = EXCLUDED.hero_subheadline, banyan_title = EXCLUDED.banyan_title;

